<?php
require __DIR__.'/includes/module.php';$owner=require_owner();$pdo=db();$bid=(int)$owner['business_id'];$error='';$modules=['dashboard','customers','leads','products','tasks','quotations','invoices','payments','expenses','reports'];$labels=['dashboard'=>'Dashboard analytics','customers'=>'Customers','leads'=>'Leads & deals','products'=>'Products & services','tasks'=>'Tasks & reminders','quotations'=>'Quotations','invoices'=>'Invoices','payments'=>'Payments','expenses'=>'Expenses','reports'=>'Reports'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');if($action==='create'){$name=post_text('name');$email=strtolower(post_text('email',190));$password=(string)($_POST['password']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12)$error='Enter a name, valid email and a password of at least 12 characters.';else{try{$pdo->beginTransaction();$pdo->prepare("INSERT INTO users(business_id,name,email,password_hash,role,active) VALUES(?,?,?,?,'manager',1)")->execute([$bid,$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$managerId=(int)$pdo->lastInsertId();$permissions=$_POST['permissions']??[];$insert=$pdo->prepare('INSERT INTO user_permissions(user_id,permission_key,granted) VALUES(?,?,?)');foreach($modules as $m){$insert->execute([$managerId,$m.'.view',isset($permissions[$m]['view'])?1:0]);$insert->execute([$managerId,$m.'.edit',isset($permissions[$m]['edit'])?1:0]);}audit('manager.create',$email);$pdo->commit();flash('Manager account created.');redirect('managers.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Manager could not be created. Check that the email is not already in use.';}}}elseif($action==='permissions'){$mid=(int)($_POST['manager_id']??0);$q=$pdo->prepare("SELECT id FROM users WHERE id=? AND business_id=? AND role='manager'");$q->execute([$mid,$bid]);if(!$q->fetchColumn())$error='Manager account not found.';else{try{$pdo->beginTransaction();$pdo->prepare('DELETE FROM user_permissions WHERE user_id=?')->execute([$mid]);$insert=$pdo->prepare('INSERT INTO user_permissions(user_id,permission_key,granted) VALUES(?,?,?)');$permissions=$_POST['permissions']??[];foreach($modules as $m){$view=isset($permissions[$m]['view']);$edit=isset($permissions[$m]['edit']);$insert->execute([$mid,$m.'.view',$view?1:0]);$insert->execute([$mid,$m.'.edit',($view&&$edit)?1:0]);}audit('manager.permissions.update','Manager ID '.$mid);$pdo->commit();flash('Manager permissions updated.');redirect('managers.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Permissions could not be saved.';}}}elseif($action==='toggle'){$mid=(int)($_POST['manager_id']??0);$pdo->prepare("UPDATE users SET active=1-active WHERE id=? AND business_id=? AND role='manager'")->execute([$mid,$bid]);audit('manager.access.toggle','Manager ID '.$mid);flash('Manager access updated.');redirect('managers.php');}}$q=$pdo->prepare("SELECT id,name,email,active,created_at FROM users WHERE business_id=? AND role='manager' ORDER BY name");$q->execute([$bid]);$rows=$q->fetchAll();$selected=(int)($_GET['edit']??0);$selectedManager=null;$grants=[];if($selected){$q=$pdo->prepare("SELECT id,name,email FROM users WHERE id=? AND business_id=? AND role='manager'");$q->execute([$selected,$bid]);$selectedManager=$q->fetch();if($selectedManager){$q=$pdo->prepare('SELECT permission_key,granted FROM user_permissions WHERE user_id=?');$q->execute([$selected]);foreach($q->fetchAll() as $grant)$grants[$grant['permission_key']]=(bool)$grant['granted'];}}page_start('Managers','managers');?><style>.manager-layout{display:grid;grid-template-columns:1fr 1fr;gap:14px}.manager-card{background:#fff;border:1px solid #edf0f2;border-radius:9px;padding:17px}.permission-table{width:100%;border-collapse:collapse}.permission-table td,.permission-table th{padding:9px 6px;border-bottom:1px solid #eff1f3;text-align:left;font-size:10px}.permission-table th{color:#8a95a1}.permission-table td:first-child{font-weight:600}.permission-table input{accent-color:#258fd2}.access-active{color:#218966}.access-disabled{color:#bf705f}@media(max-width:760px){.manager-layout{grid-template-columns:1fr}}</style><div class="section-head"><div><span class="eyebrow">ACCESS CONTROL</span><h1>Managers</h1><p>Create Manager accounts and set their workspace access.</p></div></div><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif?><div class="manager-layout"><section class="manager-card"><h2><?= $selectedManager?'Permissions · '.e($selectedManager['name']):'Manager accounts'?></h2><?php if($selectedManager):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="permissions"><input type="hidden" name="manager_id" value="<?=$selected?>"><table class="permission-table"><thead><tr><th>Module</th><th>View</th><th>Edit</th></tr></thead><tbody><?php foreach($modules as $m):?><tr><td><?=e($labels[$m])?></td><td><input type="checkbox" name="permissions[<?=e($m)?>][view]" <?=!empty($grants[$m.'.view'])?'checked':''?>></td><td><input type="checkbox" name="permissions[<?=e($m)?>][edit]" <?=!empty($grants[$m.'.edit'])?'checked':''?>></td></tr><?php endforeach?></tbody></table><button class="button primary" style="margin-top:13px">Save permissions</button><a class="button secondary" href="managers.php">Cancel</a></form><?php else:?><p class="help-text">Owners keep full access. Manager access must be granted here.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>MANAGER</th><th>ACCESS</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><div class="help-text"><?=e($r['email'])?></div></td><td class="<?=$r['active']?'access-active':'access-disabled'?>"><?=$r['active']?'Active':'Disabled'?></td><td><a class="link-button" href="managers.php?edit=<?=(int)$r['id']?>">Permissions</a><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="manager_id" value="<?=(int)$r['id']?>"><button class="link-button"><?=$r['active']?'Disable':'Enable'?></button></form></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="3" class="empty-row">No Manager accounts yet.</td></tr><?php endif?></tbody></table></div><?php endif?></section><section class="manager-card"><h2>Create Manager</h2><p class="help-text">Share the temporary password securely. Managers can change it in Settings.</p><form method="post" class="stack-form"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="create"><label>Full name<input required name="name"></label><label>Email<input required type="email" name="email"></label><label>Temporary password<input required type="password" minlength="12" name="password"></label><strong style="font-size:10px">Initial access</strong><table class="permission-table"><thead><tr><th>Module</th><th>View</th><th>Edit</th></tr></thead><tbody><?php foreach($modules as $m):?><tr><td><?=e($labels[$m])?></td><td><input type="checkbox" name="permissions[<?=e($m)?>][view]" value="1" <?=in_array($m,['dashboard','customers','tasks'],true)?'checked':''?>></td><td><input type="checkbox" name="permissions[<?=e($m)?>][edit]" value="1"></td></tr><?php endforeach?></tbody></table><button class="button primary">Create Manager</button></form></section></div><?php page_end();
